#!/usr/bin/env python3
"""Compute ground truth for CSX-140_Q1 from local event data."""

from __future__ import annotations

import json
import re
from html.parser import HTMLParser
from pathlib import Path
from typing import Any


TASK_ID = "CSX-140_Q1"
EVENT_ID = "CSX-140"


class TextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.parts: list[str] = []
        self.skip_depth = 0

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag in {"script", "style", "noscript"}:
            self.skip_depth += 1
        if tag in {"p", "h1", "h2", "h3", "li"}:
            self.parts.append("\n")

    def handle_endtag(self, tag: str) -> None:
        if tag in {"script", "style", "noscript"} and self.skip_depth:
            self.skip_depth -= 1

    def handle_data(self, data: str) -> None:
        if self.skip_depth:
            return
        text = " ".join(data.split())
        if text:
            self.parts.append(text + " ")

    def text(self) -> str:
        return " ".join("".join(self.parts).split())


def load_json(package_dir: Path, relative_path: str) -> Any:
    with (package_dir / relative_path).open("r", encoding="utf-8") as handle:
        return json.load(handle)


def html_text(package_dir: Path, relative_path: str) -> str:
    parser = TextExtractor()
    parser.feed((package_dir / relative_path).read_text(encoding="utf-8", errors="ignore"))
    return parser.text()


def first_float(pattern: str, text: str) -> float:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    if not match:
        raise ValueError(f"pattern not found: {pattern}")
    return float(match.group(1).replace(",", ""))


def first_int(pattern: str, text: str) -> int:
    return int(first_float(pattern, text))


def rounded(value: float, digits: int = 2) -> float:
    return round(float(value), digits)


def main() -> None:
    task_dir = Path(__file__).resolve().parent
    workspace_root = task_dir.parents[2]
    package_dir = workspace_root / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

    anchor_path = "data/event_reports/event_reports_003_Locked_event_anchor_March_2015_Atacama_Desert_storm_and_flash_floods.json"
    report_path = "data/other/other_001_NASA_Earth_Observatory_Flooding_in_the_Chilean_Desert.html"
    era5_path = "data/physical_hazard/physical_hazard_004_ERA5-Land_hourly_aggregate_stats.json"
    gpm_path = "data/physical_hazard/physical_hazard_006_GPM_IMERG_V07_event_accumulated_precipitation.json"
    chirps_path = "data/physical_hazard/physical_hazard_008_CHIRPS_daily_event_accumulated_precipitation.json"

    anchor = load_json(package_dir, anchor_path)
    report_text = html_text(package_dir, report_path)
    era5 = load_json(package_dir, era5_path)
    gpm = load_json(package_dir, gpm_path)
    chirps = load_json(package_dir, chirps_path)

    event_start = anchor["temporal_window"]["start_date"]
    event_end = anchor["temporal_window"]["end_date"]

    antofagasta_rain_mm = first_float(r"Antofagasta received ([\d,.]+) millimeters", report_text)
    antofagasta_annual_mm = first_float(r"yearly average of ([\d,.]+) millimeters", report_text)
    killed_at_least = first_int(r"At least ([\d,.]+) people were killed", report_text)
    missing = first_int(r"and ([\d,.]+) were still missing two weeks afterward", report_text)
    homes_swept = first_int(r"At least ([\d,.]+) homes were swept away", report_text)
    homes_damaged = first_int(r"and ([\d,.]+) more were severely damaged", report_text)

    peak_values = {
        "era5_land": rounded(era5["stats"]["precipitation_sum_mm_max"], 3),
        "gpm_imerg": rounded(gpm["stats"]["gpm_event_precip_mm_max"], 3),
        "chirps": rounded(chirps["stats"]["chirps_event_precip_mm_max"], 3),
    }
    peak_accumulation_mm = rounded(max(peak_values.values()), 1)
    product_peak_support_count = sum(value >= 30.0 for value in peak_values.values())
    annual_equiv_ratio = rounded(antofagasta_rain_mm / antofagasta_annual_mm, 2)
    homes_affected_at_least = homes_swept + homes_damaged

    threshold_passes = {
        "annual_ratio": annual_equiv_ratio >= 10,
        "peak_accumulation": peak_accumulation_mm >= 30,
        "product_support": product_peak_support_count >= 2,
    }
    classification = "arid_pulse_confirmed" if all(threshold_passes.values()) else "not_confirmed"
    check_sentence = (
        "All three arid-pulse checks pass: 24 mm is 14.12 times the 1.7 mm typical annual rainfall, "
        "the strongest gridded peak is 41.2 mm, and two gridded products have event-window peaks at or above 30 mm."
    )

    primary_gt = {
        "classification": classification,
        "annual_equiv_ratio": annual_equiv_ratio,
        "reported_one_day_mm": rounded(antofagasta_rain_mm, 1),
        "peak_accumulation_mm": peak_accumulation_mm,
        "product_peak_support_count": product_peak_support_count,
        "threshold_passes": threshold_passes,
        "impact_anchor": {
            "killed_at_least": killed_at_least,
            "missing": missing,
            "homes_affected_at_least": homes_affected_at_least,
        },
        "check_sentence": check_sentence,
    }

    computed_gt = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "target_family": "numeric_diagnosis",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "key_values": {
            "event_window": {
                "start_date": event_start,
                "end_date": event_end,
            },
            "inputs": {
                "antofagasta_rain_mm": rounded(antofagasta_rain_mm, 1),
                "antofagasta_annual_mm": rounded(antofagasta_annual_mm, 1),
                "peak_values_mm": peak_values,
                "product_peak_support_count": product_peak_support_count,
                "homes_swept_away_at_least": homes_swept,
                "homes_severely_damaged": homes_damaged,
            },
            "decision_rule": {
                "annual_equiv_ratio_min": 10,
                "peak_accumulation_mm_min": 30,
                "product_peak_support_count_min": 2,
            },
        },
        "numeric_tolerances": {
            "ratio_abs": 0.1,
            "mm_abs": 0.2,
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "Final classification",
                    "points": 4,
                    "description": "Returns arid_pulse_confirmed as the final deterministic class.",
                    "partial_credit": "Award 2 points for a passing class with a vague label; award 0-1 point if the label conflicts with the threshold ledger.",
                },
                {
                    "name": "Annual-equivalent ratio",
                    "points": 4,
                    "description": "Computes 24 divided by 1.7 and reports about 14.12 with the correct pass state.",
                    "partial_credit": "Award 2-3 points for minor rounding error; award 1 point for identifying the inputs without the quotient.",
                },
                {
                    "name": "Rainfall accumulation values",
                    "points": 4,
                    "description": "Reports 41.2 mm for the strongest gridded peak summary and counts 2 gridded products with event-window peaks at or above 30 mm.",
                    "partial_credit": "Award 2-3 points for one correct value; award 1 point for listing peak products without applying the support-count rule.",
                },
                {
                    "name": "Threshold ledger",
                    "points": 3,
                    "description": "Marks annual_ratio, peak_accumulation, and product_support as true and links the class to all three inequalities.",
                    "partial_credit": "Award 1-2 points for correct booleans without the inequality logic, or for one mistaken boolean with sound calculations.",
                },
                {
                    "name": "Impact anchor arithmetic",
                    "points": 3,
                    "description": "Reports at least 26 killed, 120 missing, and homes_affected_at_least equal to 8000.",
                    "partial_credit": "Award 1-2 points for correct casualty counts or correct housing sum, but not both.",
                },
                {
                    "name": "Compact output",
                    "points": 2,
                    "description": "Uses the requested compact JSON fields and a one-sentence computed check.",
                    "partial_credit": "Award 1 point for correct values in a less compact format or with a diffuse explanation.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                anchor_path,
                report_path,
                era5_path,
                gpm_path,
                chirps_path,
            ],
            "notes": [
                "The off-event daily point-weather fill is intentionally not used for the official answer.",
                "Rainfall-pulse support is scored from the incident report and declared package-relative gridded precipitation summaries.",
            ],
        },
    }

    with (task_dir / "computed_gt.json").open("w", encoding="utf-8") as handle:
        json.dump(computed_gt, handle, indent=2, sort_keys=True, ensure_ascii=True)
        handle.write("\n")


if __name__ == "__main__":
    main()
